.banner-section {
  color: #fff;
  background-color: #082753;
  width: 100%;
  padding: 10px 5%;
  position: relative;
}

.container-large {
  width: 100%;
  max-width: 1208px;
  margin-bottom: 0;
  margin-left: auto;
  margin-right: auto;
}

.banner-content {
  grid-column-gap: 12px;
  grid-row-gap: 12px;
  color: #fff;
  justify-content: center;
  align-items: center;
  display: flex;
}

.paragraph-regular {
  color: #fff;
  margin-bottom: 0;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 14px;
  line-height: 24px;
}

.paragraph-regular.capitalize {
  text-transform: capitalize;
}

.banner-button {
  background-color: #292929;
  border-radius: 8px;
  flex: none;
  padding: 2px 8px;
  font-size: 14px;
  line-height: 24px;
  transition: background-color .3s;
}

.banner-button:hover {
  background-color: #3d3d3d;

.nav-23-logo {
  width: 130px;
  height: 100%;
  padding-left: 0;
  padding-right: 0;
}

.nav-23-container {
  grid-column-gap: 10px;
  grid-row-gap: 10px;
  justify-content: space-between;
  width: 100%;
  max-width: none;
  margin-left: auto;
  margin-right: auto;
  display: flex;
}

.nav-23-dropdown-link {
  grid-column-gap: 12px;
  grid-row-gap: 12px;
  color: #082753;
  white-space: nowrap;
  border-radius: 8px;
  padding: 8px 24px 8px 8px;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 16px;
  font-weight: 500;
  text-decoration: none;
  transition: background-color .3s;
  display: flex;
}

.nav-23-dropdown-link:hover {
  background-color: #21cfff12;
}

.button-primary-large {
  grid-column-gap: 6px;
  grid-row-gap: 6px;
  color: #fff;
  text-align: center;
  white-space: nowrap;
  background-color: #000;
  border-radius: 10px;
  justify-content: center;
  align-items: center;
  height: 48px;
  padding: 12px;
  font-size: 16px;
  font-weight: 500;
  line-height: 1.5;
  text-decoration: none;
  transition: background-color .3s;
  display: inline-flex;
}

.nav-23-menu-line {
  transform-origin: center;
  background-color: currentColor;
  border-radius: 4px;
  width: 20px;
  height: 2px;
}

.nav-23-menu-line.line-middle {
  top: 50%;
}

.nav-23-menu-line.line-bottom {
  bottom: 0;
}

.nav-23-menu-burger {
  grid-column-gap: 4px;
  grid-row-gap: 4px;
  flex-flow: column;
  justify-content: center;
  align-items: center;
  width: 100%;
  height: 100%;
  display: flex;
}

.nav-23-left {
  grid-column-gap: 40px;
  grid-row-gap: 40px;
  flex: 0 auto;
  justify-content: flex-start;
  align-items: center;
  display: flex;
}

.nav-23-dropdown-arrow {
  color: #082753;
  justify-content: center;
  align-items: center;
  width: 24px;
  height: 24px;
  padding: 6px 2px 2px;
  font-family: Roobert PRO, Arial, sans-serif;
  font-weight: 500;
  display: flex;
}

.nav-23-links {
  grid-column-gap: 2px;
  grid-row-gap: 2px;
  justify-content: flex-start;
  align-items: center;
  display: flex;
}

.button-secondary-large {
  grid-column-gap: 6px;
  grid-row-gap: 6px;
  color: #082753;
  text-align: center;
  white-space: nowrap;
  background-color: #0000;
  border: 1px solid #082753;
  border-radius: 10px;
  justify-content: center;
  align-items: center;
  height: auto;
  padding: 8px 20px;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 13px;
  font-weight: 700;
  line-height: 1.5;
  text-decoration: none;
  display: inline-flex;
}

.button-secondary-large:hover {
  color: #fff;
  background-color: #082753;
}

.nav-23-dropdown-links {
  grid-column-gap: 2px;
  grid-row-gap: 2px;
  flex-flow: column;
  display: flex;
}

.navbar {
  z-index: 999999;
  text-align: center;
  background-color: #fff;
  width: 100%;
  padding: 6px 1%;
  position: relative;
}

.nav-23-menu-button {
  color: #fff;
  background-color: #000;
  border-radius: 10px;
  flex: none;
  width: 48px;
  height: 48px;
  padding: 0;
}

.nav-23-menu-button.w--open {
