            const linkClass =
              "flex items-center whitespace-nowrap rounded-lg pl-2 pr-6 py-2 text-[16px] font-medium text-[#082753] no-underline transition-colors duration-300 hover:bg-[#21cfff12]";

            if (child.external) {
              return (
                <a
