// ─── Newsletter (client component for form state) ─────────────────────────────

function FooterNewsletter() {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState<"idle" | "success" | "error">("idle");
  const [submitting, setSubmitting] = useState(false);

  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (!email) return;
    setSubmitting(true);
    try {
      // TODO: wire to your email collection endpoint
      await new Promise<void>((resolve) => setTimeout(resolve, 800));
      setStatus("success");
      setEmail("");
    } catch {
      setStatus("error");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    /* .footer-newsletter-card
       desktop: gap 10px, padding 30px
       479px:   gap 5px,  padding 20px 16px
    */
    <div
      className="flex flex-col rounded-[20px] max-[479px]:gap-[5px]"
      style={{
        gap: "10px",
        padding: "30px",
        backgroundColor: "rgba(255,255,255,0.3)",
        backgroundImage: "radial-gradient(circle, #092854, rgba(9,41,85,0.67))",
        border: "0.5px solid rgba(5,186,254,0.38)",
        boxShadow: "0 0 50px rgba(0,0,0,0.2), inset 0 0 100px #092955",
      }}
    >
      {/* Responsive padding override at 479px via a wrapper trick — use JS media query or CSS-in-JS isn't available,
          so we use a style tag approach via className override. Tailwind handles this with max-[479px]: prefix. */}

      {/* Title block: .footer-newsletter-title — gap 0 desktop, gap 10px at 479px */}
      <div className="flex flex-col gap-0 max-[479px]:gap-[10px]">
        {/* "Join 500+ Subscribers" pill row — .news-subhead-out: mb 15px, gap 10px; at 479px mb 0 */}
        <div
          className="flex items-center gap-[10px] max-[479px]:mb-0"
          style={{ marginBottom: "15px" }}
        >
          {/* .newsubott pill: gap 5px, bg rgba(33,207,255,0.07), border 1.5px solid #05bafe, border-radius 20px, padding 0 13px, line-height 14px */}
          <div
            className="flex items-center rounded-[20px]"
            style={{
              gap: "5px",
              padding: "0 13px",
              lineHeight: "14px",
              backgroundColor: "rgba(33,207,255,0.07)",
              border: "1.5px solid #05bafe",
            }}
          >
            <Image
              src="/images/webflow/Layer_1-57.svg"
              alt="sparkle icon"
              width={14}
              height={14}
              className="h-3.5 w-3.5"
            />
            <p className="m-0 text-left text-[12px] font-bold leading-tight text-white">
              Join 500+ Subscribers
            </p>
          </div>
        </div>

        {/* Heading */}
        <h2 className="m-0 text-left text-[22px] font-bold leading-tight text-white">
          Agency Growth Insights{" "}
          <span style={{ color: "#05bafe" }}>
            <br />
            Delivered Monthly
          </span>
        </h2>

        {/* Body */}
        <p
          className="mt-1 text-[14px] leading-6"
          style={{ color: "#c0dbff" }}
        >
          Smart growth strategies, CRM playbooks, industry trends, early product
          updates, and member-only offers — designed for modern agencies.
        </p>
      </div>

      {/* Form block — .footer-newsletter-form-block: margin-top 13px; at 479px: margin-top 0, padding 20px 0 10px */}
      <div className="max-[479px]:mt-0 max-[479px]:px-0 max-[479px]:pb-[10px] max-[479px]:pt-5" style={{ marginTop: "13px" }}>
        {status === "success" ? (
          <div className="rounded-xl bg-[#def4ff] px-4 py-3 text-sm font-medium text-[#082753]">
            Thank you! Your submission has been received!
          </div>
        ) : (
          <form onSubmit={handleSubmit}>
            {/* .column-tiny-2: position relative, flex col, gap 4px, justify center */}
            <div className="relative flex flex-col gap-1">
              {/* .text-field-small: min-height 55px, border 1px solid #edeff3, border-radius 8px, padding 8px 12px, font-size 14px */}
              <input
                type="email"
                name="email"
                id="footer-email"
                placeholder="Enter your email"
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="min-h-[55px] w-full rounded-lg border border-[#edeff3] px-3 py-2 pr-[130px] text-[14px] leading-5 text-[#23272f] outline-none placeholder:text-[#525f75] focus:border-[#b1bbc8] max-[479px]:pr-3"
                style={{ fontFamily: "inherit" }}
              />
              {/* .button-secondary-small: absolute right 1.5%, gradient bg, border-radius 10px, padding 12px 20px, font-size 16px, font-weight 700
                  at 479px: position relative, right auto, margin-top 10px */}
              <button
                type="submit"
                disabled={submitting}
                className="absolute right-[1.5%] top-1/2 -translate-y-1/2 inline-flex items-center justify-center overflow-hidden rounded-[10px] px-5 py-3 text-[16px] font-bold text-white disabled:opacity-70 max-[479px]:relative max-[479px]:right-auto max-[479px]:top-auto max-[479px]:mt-[10px] max-[479px]:translate-y-0 max-[479px]:w-full"
