function FooterLinkColumn({
  title,
  links,
}: {
  title: string;
  links: FooterLink[];
}) {
  return (
    /* .column-x-large / .column-regular-2: gap 16px, flex col */
    <div className="flex flex-col gap-4">
      {/* .footer-title: color #fff, font-size 18px, font-weight 700, line-height 22px, text-transform capitalize */}
