        {title}
      </p>
      {/* Links */}
      <div className="flex flex-col gap-4">
        {links.map((link) => {
          /* .footer-link: color rgba(255,255,255,0.80), font-size 16px, line-height 24px, hover color #fff
             at 479px: font-size 14px, line-height 20px */
          const baseClass =
            "text-[16px] leading-6 no-underline transition-colors duration-300 max-[479px]:text-[14px] max-[479px]:leading-5";
          const colorClass = "text-white/80 hover:text-white";
          const disabledStyle = link.comingSoon
            ? "pointer-events-none opacity-60"
            : "";

          const inner = (
            /* .coming-soon-out: gap 10px, display flex */
            <span className="flex items-center gap-[10px]">
              {link.label}
              {link.comingSoon && (
                /* .coming-soon-badge: color #1890ff, bg #e6f7ff, border-radius 4px, padding 2px 4px, font-size 10px, font-weight 500, line-height 12px */
                <span
                  className="inline-flex items-center rounded font-medium"
                  style={{
                    color: "#1890ff",
                    backgroundColor: "#e6f7ff",
                    padding: "2px 4px",
                    fontSize: "10px",
                    lineHeight: "12px",
                    fontWeight: 500,
                  }}
                >
                  Soon
                </span>
              )}
            </span>
          );

          if (link.external) {
            return (
              <a
                key={link.href + link.label}
                href={link.href}
                target="_blank"
                rel="noopener noreferrer"
                className={`${baseClass} ${colorClass} ${disabledStyle}`}
              >
                {inner}
              </a>
            );
          }

          return (
            <Link
              key={link.href + link.label}
              href={link.href}
              className={`${baseClass} ${colorClass} ${disabledStyle}`}
            >
              {inner}
            </Link>
          );
        })}
      </div>
    </div>
  );
}

