function SocialLink({
  href,
  label,
  children,
}: {
  href: string;
  label: string;
  children: React.ReactNode;
}) {
  const [hovered, setHovered] = useState(false);

  return (
    <a
      href={href}
      target="_blank"
      rel="noopener noreferrer"
      aria-label={label}
      className="flex h-[38px] w-[38px] shrink-0 items-center justify-center rounded-[10px] transition-shadow duration-300"
      style={{
        backgroundColor: "rgba(255,255,255,0.05)",
        boxShadow: hovered
          ? "0 2px 4px rgba(35,39,46,0.16)"
          : "0 1px 2px rgba(35,39,46,0.08)",
      }}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
    >
      {children}
    </a>
  );
}

"use client";

import Link from "next/link";
import { ChevronDown } from "lucide-react";
import { useState } from "react";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import { NAV_ITEMS, CTA_NAV } from "@/lib/constants/navigation";
import type { NavItem } from "@/types/navigation";

/*
  Webflow mobile nav theme (≤767px):
  - .nav-23-menu: bg #082753, flex-col, padding 10px 4%
  - .nav-23-link: color #fff, border-bottom 1px solid rgba(255,255,255,0.04), padding 12px 0
  - .nav-23-dropdown-toggle: color #fff, justify-content space-between, padding 12px 0,
      border-bottom 1px solid rgba(255,255,255,0.04)
  - .nav-23-dropdown-arrow: color #21cfff
  - .menu-text: color #fff
*/

function MobileNavGroup({
  item,
  onNavigate,
}: {
  item: NavItem;
  onNavigate: () => void;
}) {
  const [expanded, setExpanded] = useState(false);

  if (!item.children) {
    return (
      /* .nav-23-link at 767px: color #fff, border-bottom rgba(255,255,255,0.04), padding 12px 0 */
      <Link
        href={item.href}
        onClick={onNavigate}
        className="block px-0 py-3 text-[15px] font-medium text-white no-underline transition-colors"
        style={{ borderBottom: "1px solid rgba(255,255,255,0.04)" }}
      >
        {item.label}
      </Link>
    );
  }

  return (
    <div style={{ borderBottom: "1px solid rgba(255,255,255,0.04)" }}>
      {/* .nav-23-dropdown-toggle at 767px: color #fff, justify-content space-between, padding 12px 0 */}
      <button
        type="button"
        onClick={() => setExpanded(!expanded)}
        className="flex w-full items-center justify-between px-0 py-3 text-[15px] font-medium text-white transition-colors"
      >
        {item.label}
        {/* .nav-23-dropdown-arrow at 767px: color #21cfff */}
        <ChevronDown
          className={`h-4 w-4 transition-transform duration-200 ${expanded ? "rotate-180" : ""}`}
          style={{ color: "#21cfff" }}
        />
      </button>

      {expanded && (
        /* Expanded dropdown children */
        <div className="mb-2 flex flex-col gap-0.5">
          {item.children.map((child) => {
            const content = (
              <>
                <span className="text-[14px] font-medium text-white/90">
                  {child.label}
                </span>
                {child.comingSoon && (
                  <span
                    className="inline-flex items-center rounded font-medium"
                    style={{
                      color: "#1890ff",
                      backgroundColor: "#e6f7ff",
                      padding: "2px 4px",
                      fontSize: "9px",
                      lineHeight: "1em",
                    }}
                  >
                    Coming Soon
                  </span>
                )}
              </>
            );

            if (child.comingSoon) {
              return (
                <div
                  key={child.href}
                  className="flex cursor-default items-center gap-2 rounded-lg px-3 py-2.5 opacity-50"
                >
                  {content}
                </div>
              );
            }

            if (child.external) {
              return (
                <a
                  key={child.href}
                  href={child.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  onClick={onNavigate}
                  className="flex items-center gap-2 rounded-lg px-3 py-2.5 no-underline transition-colors hover:bg-white/5"
                >
                  {content}
                </a>
              );
            }

            return (
              <Link
                key={child.href}
                href={child.href}
                onClick={onNavigate}
                className="flex items-center gap-2 rounded-lg px-3 py-2.5 no-underline transition-colors hover:bg-white/5"
              >
                {content}
              </Link>
            );
          })}
        </div>
      )}
    </div>
  );
}

export function MobileNav({
  open,
  onClose,
}: {
  open: boolean;
  onClose: () => void;
}) {
  return (
    <Sheet open={open} onOpenChange={onClose}>
      {/* Dark navy background matching Webflow .nav-23-menu at 767px: bg #082753 */}
      <SheetContent
        side="right"
        className="flex w-[300px] flex-col p-0"
        style={{ backgroundColor: "#082753", borderLeft: "1px solid rgba(255,255,255,0.08)" }}
      >
        {/* Header */}
        <SheetHeader
          className="px-4 py-4"
          style={{ borderBottom: "1px solid rgba(255,255,255,0.08)" }}
        >
          <div className="flex items-center justify-between">
            <SheetTitle className="text-lg font-bold text-white">
              Boldteq
            </SheetTitle>
          </div>
        </SheetHeader>

        {/* Nav links — .nav-23-menu at 767px: padding 10px 4% */}
        <div className="flex flex-col overflow-y-auto px-4 py-[10px]">
          {NAV_ITEMS.map((item) => (
            <MobileNavGroup
              key={item.label}
              item={item}
              onNavigate={onClose}
            />
          ))}
        </div>

        {/* CTA buttons */}
        <div
          className="mt-auto space-y-3 px-4 py-4"
          style={{ borderTop: "1px solid rgba(255,255,255,0.08)" }}
        >
          {/* Login — .button-secondary-large adapted for dark bg: white border + white text */}
          <a
            href={CTA_NAV[0].href}
            target="_blank"
            rel="noopener noreferrer"
            onClick={onClose}
            className="flex w-full items-center justify-center rounded-[10px] border px-5 py-2.5 text-[13px] font-bold text-white no-underline transition-colors hover:bg-white/10"
            style={{ borderColor: "rgba(255,255,255,0.3)" }}
          >
            {CTA_NAV[0].label}
          </a>

          {/* Schedule Demo */}
          <Link
            href={CTA_NAV[1].href}
            onClick={onClose}
            className="flex w-full items-center justify-center rounded-[0.75rem] px-5 py-2.5 text-[13px] font-bold text-white no-underline"
            style={{ background: "linear-gradient(90deg, #21cfff, #019ae6)" }}
          >
            {CTA_NAV[1].label}
          </Link>
        </div>
      </SheetContent>
    </Sheet>
  );
}
